import React, { useRef } from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();
  const systemRef = useRef(null);

  const handleMouseMove = (e) => {
    const el = systemRef.current;
    if (!el) return;

    const { left, top, width, height } =
      el.getBoundingClientRect();

    const x = (e.clientX - left) / width - 0.5;
    const y = (e.clientY - top) / height - 0.5;

    const rotateX = y * -15;
    const rotateY = x * 15;

    el.style.transform = `
      perspective(1000px)
      rotateX(${rotateX}deg)
      rotateY(${rotateY}deg)
    `;
  };

  const resetTilt = () => {
    const el = systemRef.current;
    if (!el) return;

    el.style.transform = `
      perspective(1000px)
      rotateX(0deg)
      rotateY(0deg)
    `;
  };

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Thinker • Problem Solver
          </h2>

          <p className="desc">
            I design structured systems and build scalable applications with clarity,
            performance, and real-world impact.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>

            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT - 3D ORBIT SYSTEM */}
        <div className="right">

          <div
            className="system"
            ref={systemRef}
            onMouseMove={handleMouseMove}
            onMouseLeave={resetTilt}
          >

            {/* RINGS */}
            <div className="ring ring1"></div>
            <div className="ring ring2"></div>

            {/* CENTER */}
            <div className="center">
              <img
                src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
                alt="avatar"
              />
              <p>Swetha A</p>
            </div>

            {/* ORBIT */}
            <div className="orbit">

              <div className="node n1">React</div>
              <div className="node n2">Java</div>
              <div className="node n3">Spring Boot</div>
              <div className="node n4">MySQL</div>

            </div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
          overflow: hidden;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 {
          font-size: 62px;
          margin: 10px 0;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          cursor: pointer;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* RIGHT SYSTEM */
        .system {
          position: relative;
          width: 340px;
          height: 340px;
          margin: auto;

          transform-style: preserve-3d;
          transition: transform 0.2s ease-out;
        }

        /* RINGS */
        .ring {
          position: absolute;
          border-radius: 50%;
          border: 1px solid rgba(56,189,248,0.35);
          transform: translateZ(0);
        }

        .ring1 {
          width: 320px;
          height: 320px;
          top: 10px;
          left: 10px;
          animation: spin 18s linear infinite;
        }

        .ring2 {
          width: 240px;
          height: 240px;
          top: 50px;
          left: 50px;
          border: 1px dashed rgba(56,189,248,0.25);
          animation: spinReverse 14s linear infinite;
        }

        @keyframes spin {
          100% { transform: rotate(360deg); }
        }

        @keyframes spinReverse {
          100% { transform: rotate(-360deg); }
        }

        /* CENTER */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%,-50%) translateZ(40px);
          text-align: center;
          z-index: 2;
        }

        .center img {
          width: 95px;
          height: 95px;
          border-radius: 50%;
          border: 2px solid rgba(56,189,248,0.4);
          box-shadow: 0 0 25px rgba(56,189,248,0.15);
        }

        .center p {
          font-size: 13px;
          color: #94a3b8;
        }

        /* ORBIT LAYER */
        .orbit {
          position: absolute;
          width: 100%;
          height: 100%;
          animation: spin 10s linear infinite;
          transform-style: preserve-3d;
        }

        .node {
          position: absolute;
          padding: 7px 12px;
          border-radius: 18px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.25);
          font-size: 12px;
          color: #cbd5e1;
          white-space: nowrap;
          transform: translateZ(60px);
        }

        .n1 { top: 0; left: 50%; transform: translateX(-50%) translateZ(60px); }
        .n2 { top: 50%; right: 0; transform: translateY(-50%) translateZ(60px); }
        .n3 { bottom: 0; left: 50%; transform: translateX(-50%) translateZ(60px); }
        .n4 { top: 50%; left: 0; transform: translateY(-50%) translateZ(60px); }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          h1 {
            font-size: 42px;
          }

          .buttons {
            justify-content: center;
          }

          .system {
            margin-top: 40px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
